import { useEffect } from "react";

/** 再読込ガード: 60秒窓で1回のみ (無限リロードループ防止) */
const GUARD_KEY = "solopti.selfrecovery.chunk-reload-at";
const GUARD_WINDOW_MS = 60000;

/** chunk 読込失敗と判定するパターン (Next.js / Webpack / ES Modules 各系統) */
const CHUNK_ERROR_PATTERNS: RegExp[] = [
  /ChunkLoadError/i,
  /Loading chunk [^\s]+ failed/i,
  /Loading CSS chunk/i,
  /Failed to fetch dynamically imported module/i,
  /Importing a module script failed/i,
  /error loading dynamically imported module/i,
];

/** エラーオブジェクト/文字列から判定用テキストを安全に取り出す */
function textOf(input: unknown): string {
  if (!input) return "";
  if (typeof input === "string") return input;
  const obj = input as { name?: unknown; message?: unknown };
  const parts: string[] = [];
  if (typeof obj.name === "string") parts.push(obj.name);
  if (typeof obj.message === "string") parts.push(obj.message);
  return parts.join(" ");
}

function isChunkLoadFailure(text: string): boolean {
  if (!text) return false;
  for (const pattern of CHUNK_ERROR_PATTERNS) {
    if (pattern.test(text)) return true;
  }
  return false;
}

/** 「読み込み直しています…」日本語オーバーレイ (CSS 未読込でも表示できるよう DOM 直生成+インラインスタイル) */
function showReloadingOverlay(): void {
  if (document.getElementById("solopti-self-recovery-overlay")) return;
  const overlay = document.createElement("div");
  overlay.id = "solopti-self-recovery-overlay";
  overlay.setAttribute(
    "style",
    [
      "position:fixed", "top:0", "left:0", "right:0", "bottom:0",
      "z-index:2147483646", "display:flex", "flex-direction:column",
      "align-items:center", "justify-content:center", "gap:16px",
      "background:rgba(255,255,255,0.96)",
      "font-family:-apple-system,BlinkMacSystemFont,'Hiragino Sans','Noto Sans JP',sans-serif",
    ].join(";")
  );
  const style = document.createElement("style");
  style.textContent = "@keyframes solopti-sr-spin{to{transform:rotate(360deg)}}";
  const spinner = document.createElement("div");
  spinner.setAttribute(
    "style",
    "width:40px;height:40px;border-radius:9999px;border:4px solid #e5e7eb;border-top-color:#0284c7;animation:solopti-sr-spin 0.8s linear infinite;"
  );
  const label = document.createElement("div");
  label.textContent = "読み込み直しています…";
  label.setAttribute("style", "font-size:14px;color:#374151;font-weight:600;");
  overlay.appendChild(style);
  overlay.appendChild(spinner);
  overlay.appendChild(label);
  document.body.appendChild(overlay);
}

/** ガード付き自動再読込 (60秒窓で1回のみ)。sessionStorage 不可時は安全側=何もしない */
function attemptRecovery(): void {
  let last = 0;
  try {
    last = Number(window.sessionStorage.getItem(GUARD_KEY) || 0);
  } catch {
    return; // ガードを保証できない環境では自動再読込しない (ループ防止最優先)
  }
  const now = Date.now();
  if (now - last < GUARD_WINDOW_MS) return; // 窓内は再読込済み → 二重再読込しない
  try {
    window.sessionStorage.setItem(GUARD_KEY, String(now));
  } catch {
    return;
  }
  showReloadingOverlay();
  window.setTimeout(() => {
    window.location.reload();
  }, 250);
}

/**
 * ChunkRecovery — chunk 読込失敗の自己回復部品。
 * 開発/本番サーバー再起動後の「古いタブが古い部品配置を参照して読込失敗」を、
 * お客様の操作なしで自動再読込1回により回復する。
 */
export default function ChunkRecovery(): null {
  useEffect(() => {
    const onError = (event: ErrorEvent) => {
      const text = `${event.message || ""} ${textOf(event.error)}`;
      if (isChunkLoadFailure(text)) attemptRecovery();
    };
    const onRejection = (event: PromiseRejectionEvent) => {
      if (isChunkLoadFailure(textOf(event.reason))) attemptRecovery();
    };
    window.addEventListener("error", onError);
    window.addEventListener("unhandledrejection", onRejection);
    return () => {
      window.removeEventListener("error", onError);
      window.removeEventListener("unhandledrejection", onRejection);
    };
  }, []);
  return null;
}

export { ChunkRecovery };
